-- The lexer's errors are Lua 5.1's (read_numeral, read_string,
-- read_long_string), and it accepts what Lua 5.1 accepts: gopher-lua's
-- said "unterminated string", "invalid multiline string" and accepted
-- nested [[ ]], "\300" (as a byte 44), its errors were on other lines.
local function try(src)
  local f, err = loadstring(src, "=src")
  if f then
    print("ok", f())
  else
    err = err:gsub("^[^:]*:", ""):gsub("[^%w%p ]", function(c) return "\\" .. c:byte() end)
    print(err)
  end
end
